-- 0047: General Science batch 7 — chapters 906, 907, 908, 909, 910
-- Each chapter: 4 govt_technical, 4 govt_basic, 1 shared svg (level_id null). 9 atoms per chapter.

with src as (
  select v.chapter_id, v.level_id, v.atom_key, v.atom_type, v.atom_order, v.title, v.body::jsonb as body
  from (values
  (906,'govt_technical','photo-concept','concept',1,'प्रकाश संश्लेषण — SSC JE / RRB JE',$j${"note":"परीक्षा में प्रकाश संश्लेषण के लिए आवश्यक कारक और अभिक्रिया के चरण अक्सर पूछे जाते हैं।","text":"हरे पौधे क्लोरोफिल की उपस्थिति में सूर्य के प्रकाश से CO₂ और जल का उपयोग करके ग्लूकोज़ बनाते हैं और ऑक्सीजन मुक्त करते हैं। अभिक्रिया के दो चरण हैं: प्रकाश अभिक्रिया (थायलाकॉइड में, ATP और NADPH बनते हैं) और अप्रकाश अभिक्रिया या कैल्विन चक्र (स्ट्रोमा में, CO₂ स्थिर होती है)।"}$j$),
  (906,'govt_technical','photo-formula','formula',2,'प्रकाश संश्लेषण का समीकरण',$j${"formula":"6CO₂ + 12H₂O → C₆H₁₂O₆ + 6O₂ + 6H₂O (प्रकाश, क्लोरोफिल)","explanation":"जल का अपघटन प्रकाश अभिक्रिया में होता है, जिससे O₂ निकलती है"}$j$),
  (906,'govt_technical','photo-example','example',3,'Numerical (JE style)',$j${"question":"प्रकाश संश्लेषण के लिए CO₂ का कौन सा स्रोत है और ऑक्सीजन कहाँ से निकलती है?","solution":"CO₂ वायुमंडल से रंध्रों (stomata) द्वारा ली जाती है; O₂ जल के अपघटन से प्रकाश अभिक्रिया में निकलती है","answer":"वायुमंडल; जल का अपघटन"}$j$),
  (906,'govt_technical','photo-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"प्रकाश अभिक्रिया किस भाग में होती है?","options":["थायलाकॉइड झिल्ली","स्ट्रोमा","माइटोकॉन्ड्रिया","नाभिक"],"answer":0,"explanation":"प्रकाश अभिक्रिया क्लोरोप्लास्ट के थायलाकॉइड में होती है।"},{"q":"प्रकाश संश्लेषण में निकलने वाली गैस कौन सी है?","options":["ऑक्सीजन","नाइट्रोजन","हाइड्रोजन","कार्बन मोनोऑक्साइड"],"answer":0,"explanation":"जल के अपघटन से ऑक्सीजन मुक्त होती है।"}]}$j$),
  (906,'govt_basic','photo-concept','concept',1,'प्रकाश संश्लेषण',$j${"note":"परीक्षा में पौधे अपना भोजन कैसे बनाते हैं, यह पूछा जाता है।","text":"पौधे सूर्य की ऊर्जा से कार्बन डाइऑक्साइड और पानी को मिलाकर ग्लूकोज़ बनाते हैं। इस क्रिया में ऑक्सीजन बाहर निकलती है। इसीलिए पौधों को स्वपोषी कहते हैं।"}$j$),
  (906,'govt_basic','photo-formula','formula',2,'आवश्यक कारक',$j${"formula":"प्रकाश + क्लोरोफिल + CO₂ + जल → ग्लूकोज़ + ऑक्सीजन","explanation":"इनमें से किसी एक कारक की कमी से क्रिया धीमी हो जाती है"}$j$),
  (906,'govt_basic','photo-example','example',3,'उदाहरण',$j${"question":"पौधे रात में प्रकाश संश्लेषण क्यों नहीं करते?","solution":"प्रकाश संश्लेषण के लिए सूर्य का प्रकाश चाहिए, जो रात में नहीं मिलता","answer":"प्रकाश नहीं होता"}$j$),
  (906,'govt_basic','photo-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"पौधों में हरा रंग किस रसायन से होता है?","options":["क्लोरोफिल","हीमोग्लोबिन","मेलेनिन","कैरोटीन"],"answer":0,"explanation":"क्लोरोफिल पौधों को हरा रंग देता है और प्रकाश ऊर्जा सोखता है।"},{"q":"पत्तियों में गैसों का आदान-प्रदान किन छिद्रों से होता है?","options":["रंध्र (stomata)","जड़ रोम","बीजपत्र","कांटे"],"answer":0,"explanation":"रंध्र CO₂ और O₂ के आदान-प्रदान का मार्ग है।"}]}$j$),
  (906,null,'photo-diagram','svg',5,'प्रकाश संश्लेषण का प्रवाह',$j${"svg":"<svg viewBox='0 0 300 120' xmlns='http://www.w3.org/2000/svg'><rect x='20' y='40' width='80' height='40' fill='#fde047' rx='6'/><text x='60' y='64' text-anchor='middle' font-size='11' fill='#0f172a'>प्रकाश + जल</text><rect x='130' y='40' width='60' height='40' fill='#86efac' rx='6'/><text x='160' y='64' text-anchor='middle' font-size='11' fill='#0f172a'>पत्ती</text><rect x='220' y='40' width='70' height='40' fill='#60a5fa' rx='6'/><text x='255' y='64' text-anchor='middle' font-size='11' fill='#0f172a'>ग्लूकोज़+O₂</text></svg>","caption":"प्रकाश और जल से पत्ती में ग्लूकोज़ और ऑक्सीजन बनते हैं"}$j$),
  (907,'govt_technical','dig-concept','concept',1,'पाचन तंत्र — SSC JE / RRB JE',$j${"note":"परीक्षा में पाचक एंजाइम, उनके स्रोत और कार्य अक्सर पूछे जाते हैं।","text":"भोजन का यांत्रिक और रासायनिक पाचन मुख में शुरू होता है और छोटी आंत में पूरा होता है। लार में टायलिन (एमाइलेज) स्टार्च तोड़ता है, आमाशय का पेप्सिन प्रोटीन पचाता है, अग्न्याशय का ट्रिप्सिन और लाइपेज प्रोटीन व वसा पचाते हैं, और यकृत का पित्त वसा का इमल्शन करता है।"}$j$),
  (907,'govt_technical','dig-formula','formula',2,'एंजाइम और उनका कार्य',$j${"formula":"टायलिन → स्टार्च · पेप्सिन → प्रोटीन · लाइपेज → वसा","explanation":"पित्त एंजाइम नहीं है; यह वसा को छोटी बूंदों में तोड़ता है (इमल्सीफिकेशन)"}$j$),
  (907,'govt_technical','dig-example','example',3,'Numerical (JE style)',$j${"question":"वसा का पाचन किस अंग में सबसे अधिक होता है?","solution":"वसा का अधिकांश पाचन छोटी आंत में होता है, जहाँ अग्न्याशय का लाइपेज और पित्त काम करते हैं","answer":"छोटी आंत"}$j$),
  (907,'govt_technical','dig-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"प्रोटीन का पाचन आमाशय में किस एंजाइम से होता है?","options":["पेप्सिन","टायलिन","लाइपेज","माल्टेज"],"answer":0,"explanation":"पेप्सिन आमाशय में प्रोटीन को पेप्टाइड में तोड़ता है।"},{"q":"पित्त रस कहाँ बनता है?","options":["यकृत","आमाशय","अग्न्याशय","प्लीहा"],"answer":0,"explanation":"पित्त यकृत में बनता है और पित्ताशय में संग्रहित होता है।"}]}$j$),
  (907,'govt_basic','dig-concept','concept',1,'पाचन तंत्र',$j${"note":"परीक्षा में भोजन का मार्ग और अंगों के नाम पूछे जाते हैं।","text":"भोजन का मार्ग मुख, ग्रसनी, ग्रासनली, आमाशय, छोटी आंत और बड़ी आंत है। पचा हुआ भोजन छोटी आंत में अवशोषित होता है।"}$j$),
  (907,'govt_basic','dig-formula','formula',2,'भोजन का मार्ग',$j${"formula":"मुख → ग्रासनली → आमाशय → छोटी आंत → बड़ी आंत","explanation":"पोषक तत्वों का अवशोषण मुख्यतः छोटी आंत में होता है"}$j$),
  (907,'govt_basic','dig-example','example',3,'उदाहरण',$j${"question":"भोजन के पोषक तत्व रक्त में कहाँ से प्रवेश करते हैं?","solution":"छोटी आंत की दीवार की रसांकुर (villi) से पोषक तत्व रक्त में जाते हैं","answer":"छोटी आंत"}$j$),
  (907,'govt_basic','dig-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"मनुष्य में सबसे लंबी आहार नली का भाग कौन सा है?","options":["छोटी आंत","बड़ी आंत","आमाशय","ग्रासनली"],"answer":0,"explanation":"छोटी आंत लगभग 6–7 मीटर लंबी होती है।"},{"q":"लार में कौन सा एंजाइम होता है?","options":["टायलिन","पेप्सिन","ट्रिप्सिन","लाइपेज"],"answer":0,"explanation":"टायलिन लार में होता है और स्टार्च को पचाता है।"}]}$j$),
  (907,null,'dig-diagram','svg',5,'पाचन तंत्र का मार्ग',$j${"svg":"<svg viewBox='0 0 300 120' xmlns='http://www.w3.org/2000/svg'><g font-size='11' fill='#0f172a' text-anchor='middle'><rect x='10' y='45' width='45' height='30' fill='#fca5a5' rx='4'/><text x='32' y='64'>मुख</text><rect x='70' y='45' width='50' height='30' fill='#fdba74' rx='4'/><text x='95' y='64'>आमाशय</text><rect x='135' y='45' width='60' height='30' fill='#fde047' rx='4'/><text x='165' y='64'>छोटी आंत</text><rect x='210' y='45' width='60' height='30' fill='#86efac' rx='4'/><text x='240' y='64'>बड़ी आंत</text></g><text x='150' y='112' text-anchor='middle' fill='#64748b' font-size='11'>भोजन का मार्ग</text></svg>","caption":"मुख से बड़ी आंत तक भोजन का मार्ग"}$j$),
  (908,'govt_technical','resp-concept','concept',1,'श्वसन — SSC JE / RRB JE',$j${"note":"परीक्षा में वायवीय और अवायवीय श्वसन का अंतर और ATP की संख्या अक्सर पूछी जाती है।","text":"श्वसन में ग्लूकोज़ का ऑक्सीकरण होकर ऊर्जा (ATP) मुक्त होती है। वायवीय श्वसन में ऑक्सीजन लगती है और CO₂ व जल बनते हैं; अवायवीय श्वसन में ऑक्सीजन नहीं लगती और इथेनॉल या लैक्टिक अम्ल बनता है। श्वसन माइटोकॉन्ड्रिया में होता है।"}$j$),
  (908,'govt_technical','resp-formula','formula',2,'वायवीय श्वसन का समीकरण',$j${"formula":"C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O + ऊर्जा (ATP)","explanation":"यह अभिक्रिया माइटोकॉन्ड्रिया में होती है"}$j$),
  (908,'govt_technical','resp-example','example',3,'Numerical (JE style)',$j${"question":"यीस्ट अवायवीय श्वसन में ग्लूकोज़ से क्या बनाता है?","solution":"यीस्ट अवायवीय श्वसन से ग्लूकोज़ को इथेनॉल और CO₂ में बदलता है (किण्वन)","answer":"इथेनॉल और CO₂"}$j$),
  (908,'govt_technical','resp-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"कोशिका में श्वसन की मुख्य इकाई कौन सी है?","options":["माइटोकॉन्ड्रिया","राइबोसोम","लाइसोसोम","गॉल्जी काय"],"answer":0,"explanation":"माइटोकॉन्ड्रिया ATP बनाने के लिए श्वसन करता है।"},{"q":"मांसपेशियों में थकान के समय कौन सा अम्ल बनता है?","options":["लैक्टिक अम्ल","एसिटिक अम्ल","साइट्रिक अम्ल","कार्बोनिक अम्ल"],"answer":0,"explanation":"अवायवीय श्वसन से मांसपेशियों में लैक्टिक अम्ल बनता है।"}]}$j$),
  (908,'govt_basic','resp-concept','concept',1,'श्वसन',$j${"note":"परीक्षा में श्वसन और श्वास लेने के अंतर पर प्रश्न आते हैं।","text":"श्वसन वह क्रिया है जिसमें कोशिकाएँ भोजन से ऊर्जा निकालती हैं। श्वास लेना (breathing) केवल हवा अंदर-बाहर करने की क्रिया है। दोनों अलग हैं।"}$j$),
  (908,'govt_basic','resp-formula','formula',2,'श्वसन के प्रकार',$j${"formula":"वायवीय = ऑक्सीजन की उपस्थिति में · अवायवीय = ऑक्सीजन के बिना","explanation":"यीस्ट और जीवाणु अवायवीय श्वसन करते हैं"}$j$),
  (908,'govt_basic','resp-example','example',3,'उदाहरण',$j${"question":"मनुष्य में फेफड़ों में गैसों का आदान-प्रदान किस रूप में होता है?","solution":"फेफड़ों की वायुकोशिकाओं (alveoli) में O₂ रक्त में जाती है और CO₂ बाहर आती है","answer":"वायुकोशिकाओं में विसरण"}$j$),
  (908,'govt_basic','resp-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"मनुष्य में गैसीय आदान-प्रदान का मुख्य स्थान कौन सा है?","options":["वायुकोशिका (alveoli)","ग्रासनली","आमाशय","यकृत"],"answer":0,"explanation":"वायुकोशिकाओं में O₂ और CO₂ का विसरण होता है।"},{"q":"श्वसन में ऊर्जा किस रूप में संग्रहित होती है?","options":["ATP","DNA","प्रोटीन","हीमोग्लोबिन"],"answer":0,"explanation":"श्वसन से बनी ऊर्जा ATP में संग्रहित होती है।"}]}$j$),
  (908,null,'resp-diagram','svg',5,'श्वसन का सार',$j${"svg":"<svg viewBox='0 0 300 120' xmlns='http://www.w3.org/2000/svg'><rect x='20' y='45' width='80' height='30' fill='#86efac' rx='6'/><text x='60' y='64' text-anchor='middle' font-size='11' fill='#0f172a'>ग्लूकोज़ + O₂</text><rect x='200' y='45' width='80' height='30' fill='#fde047' rx='6'/><text x='240' y='64' text-anchor='middle' font-size='11' fill='#0f172a'>ATP + CO₂ + H₂O</text><line x1='105' y1='60' x2='195' y2='60' stroke='#64748b' stroke-width='2'/></svg>","caption":"श्वसन में ग्लूकोज़ का ऑक्सीकरण होकर ऊर्जा निकलती है"}$j$),
  (909,'govt_technical','circ-concept','concept',1,'परिसंचरण तंत्र — SSC JE / RRB JE',$j${"note":"परीक्षा में हृदय के कक्षों की संख्या, धमनी व शिरा का अंतर और रक्त के घटक अक्सर पूछे जाते हैं।","text":"मनुष्य का हृदय चार कक्षों का होता है: दो अलिंद और दो निलय। धमनी ऑक्सीजन युक्त रक्त (फुफ्फुसीय धमनी को छोड़कर) हृदय से शरीर में ले जाती है, और शिरा शरीर से वापस हृदय में लाती है। लाल रक्त कणिकाओं में हीमोग्लोबिन होता है, जो O₂ का वहन करता है।"}$j$),
  (909,'govt_technical','circ-formula','formula',2,'रक्त के घटक',$j${"formula":"रक्त = प्लाज्मा + RBC + WBC + प्लेटलेट्स","explanation":"RBC O₂ का वहन करती है, WBC रोग प्रतिरोध करती है, प्लेटलेट्स रक्त को जमाती हैं"}$j$),
  (909,'govt_technical','circ-example','example',3,'Numerical (JE style)',$j${"question":"मनुष्य का सामान्य रक्तचाप कितना होता है?","solution":"सामान्य रक्तचाप लगभग 120/80 mm Hg होता है, जहाँ 120 सिस्टोलिक और 80 डायस्टोलिक है","answer":"120/80 mm Hg"}$j$),
  (909,'govt_technical','circ-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"मनुष्य के हृदय में कितने कक्ष होते हैं?","options":["चार","दो","तीन","पाँच"],"answer":0,"explanation":"दो अलिंद और दो निलय, कुल चार कक्ष।"},{"q":"ऑक्सीजन का वहन कौन सी कोशिका करती है?","options":["लाल रक्त कणिका (RBC)","श्वेत रक्त कणिका (WBC)","प्लेटलेट्स","प्लाज्मा"],"answer":0,"explanation":"RBC में हीमोग्लोबिन होता है, जो O₂ से जुड़कर उसे ले जाता है।"}]}$j$),
