  (910,'govt_technical','trans-concept','concept',1,'पौधों में परिवहन — SSC JE / RRB JE',$j${"note":"परीक्षा में जाइलम में जल का ऊपर चढ़ना (ट्रांसपिरेशन पुल) और रंध्र का कार्य अक्सर पूछा जाता है।","text":"पौधों में जल और खनिज का परिवहन जाइलम से होता है, जो जड़ से पत्ती तक जल को ऊपर खींचता है। भोजन का परिवहन फ्लोएम से होता है। जल ऊपर चढ़ने के लिए वाष्पोत्सर्जन (transpiration) से उत्पन्न खिंचाव (transpiration pull) और संसंजन-आसंजन बल सहायक होते हैं।"}$j$),
  (910,'govt_technical','trans-formula','formula',2,'वाष्पोत्सर्जन',$j${"formula":"वाष्पोत्सर्जन = पत्तियों से जल-वाष्प का निकलना (मुख्यतः रंध्र से)","explanation":"यह जल को जड़ से ऊपर खींचने में मदद करता है"}$j$),
