  (910,'govt_technical','trans-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"पौधों में जल का वाष्पोत्सर्जन मुख्यतः किस भाग से होता है?","options":["रंध्र (stomata)","जड़","तना","बीज"],"answer":0,"explanation":"अधिकांश वाष्पोत्सर्जन पत्तियों के रंध्र से होता है।"},{"q":"भोजन (शर्करा) का परिवहन किस ऊतक से होता है?","options":["फ्लोएम","जाइलम","कॉर्क","एपिडर्मिस"],"answer":0,"explanation":"फ्लोएम पत्ती से शेष पौधे तक भोजन पहुँचाता है।"}]}$j$),
  (910,'govt_basic','trans-concept','concept',1,'पौधों में परिवहन',$j${"note":"परीक्षा में जल और भोजन के परिवहन का अंतर पूछा जाता है।","text":"पौधे जड़ से पानी लेते हैं और उसे पत्तियों तक पहुँचाते हैं। यह कार्य जाइलम करता है। पत्तियों का बना भोजन फ्लोएम से पूरे पौधे में जाता है।"}$j$),
