  (910,'govt_basic','trans-example','example',3,'उदाहरण',$j${"question":"पौधे की जड़ से पानी पत्ती तक कौन सा ऊतक ले जाता है?","solution":"जाइलम जड़ से पत्ती तक जल और खनिज को ऊपर की ओर ले जाता है","answer":"जाइलम"}$j$),
